// Replace with your real Wistia video IDs (public.vsls.wistia_video_id in AscendOS).
const wistiaVideoIds = [
  "REPLACE_WITH_REAL_WISTIA_VIDEO_ID_1",
  "REPLACE_WITH_REAL_WISTIA_VIDEO_ID_2"
];
return wistiaVideoIds.map((id) => ({ json: { wistia_video_id: id } }));

const wistiaResponse = $input.item.json;
const videoId = $('VSL video IDs to poll (edit me)').item.json.wistia_video_id;
const stats = wistiaResponse.stats ?? wistiaResponse;

return [{
  json: {
    event_type: "vsl_metric_snapshot",
    data: {
      wistia_video_id: videoId,
      video_name: wistiaResponse.name ?? undefined,
      total_plays: stats.play_count ?? 0,
      unique_viewers: stats.visitors ?? 0,
      play_rate: stats.play_rate ?? 0,
      avg_percent_watched: stats.engagement ?? 0,
      page_loads: stats.load_count ?? 0,
      engagement_json: stats.engagement_json ?? null,
      captured_at: new Date().toISOString()
    }
  }
}];
